#define MAX_STEPS 100
#define MAX_DIST 200.
#define SURF_DIST .01

float dBox(vec3 p, vec3 s) {
    return length(max(abs(p) - s, 0.));
}

float getDist(vec3 p) {
    vec4 s = vec4(0, 1, 8, 1);

    float sphereDist = length(p - s.xyz) - s.w;
    float planeDist = p.y;

    float dBoxes[] = float[](
        dBox(p - vec3(-2,.5, 0), vec3(0.2, 2, 0.2)),
        dBox(p - vec3(-1.5, 2.3, 0), vec3(0.5, 0.2, 0.2)),
        dBox(p - vec3(-1.5, 1.5, 0), vec3(0.3, 0.2, 0.2)),
        dBox(p - vec3(-0.4,.5, 0), vec3(0.2, 2, 0.2)),
        dBox(p - vec3(0.1, 2.3, 0), vec3(0.5, 0.2, 0.2)),
        dBox(p - vec3(0.1, 1.3, 0), vec3(0.3, 0.2, 0.2)),
        dBox(p - vec3(0.1, 0.2, 0), vec3(0.5, 0.2, 0.2)),
        dBox(p - vec3(1.2,.5, 0), vec3(0.2, 2, 0.2)),
        dBox(p - vec3(1.8, 0.2, 0), vec3(0.5, 0.2, 0.2))
    );

    //float d = min(sphereDist, planeDist);
    float d = planeDist;

    for (int i = 0; i < 9; i++) {
        d = min(d, dBoxes[i]);
    }

    return d;
}

float RayMarch(vec3 ro, vec3 rd) {
    float dO = 0.; 

    for(int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + rd * dO;
        float dist = getDist(p);
        dO += dist;
        if(dO > MAX_DIST || dist < SURF_DIST) break;
    }

    return dO;
}

vec3 getNormal(vec3 p) {
    float d = getDist(p);
    vec2 e = vec2(.01, 0);

    vec3 n = d - vec3(
        getDist(p-e.xyy),
        getDist(p-e.yxy),
        getDist(p-e.yyx));

    return normalize(n);   
}

float getLight(vec3 p) {
    vec3 lightPos = vec3(0, 4, -3);
   // lightPos.xz += vec2(sin(iTime) * 2., cos(iTime) * 2.);
    vec3 l = normalize(lightPos - p);
    vec3 n = getNormal(p);

    float dif = dot(n, l);
    float d = RayMarch(p + n * SURF_DIST, l);
    if (d < length(lightPos - p)) dif *= .5; 
    return dif;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;
    vec3 ro = vec3(-sin(iTime) * 6., 1, -cos(iTime) * 6.);
    vec3 rd = normalize(vec3(sin(iTime), uv.y, cos(iTime)));
    rd = rd + vec3(rd.z, 0, -rd.x) * uv.x;

    float d = RayMarch(ro, rd);

    vec3 p = ro + rd * d;

    float dif = getLight(p);
    vec3 col = vec3(dif, 0, dif/2.);

    fragColor = vec4(col, 0);
}
